import sys, os
sys.path.append('storage/ariadne')

import jax
import jax.numpy as jnp
import numpy as np
import optax

from models_fact_ln import Osc2CtxAdaptiveFactorizedL_LN
from losses import mae_with_temporal_curvature

BASE_SEED = 42
BATCH_SIZE = 8

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'rank_k': 320,
        'proj_rank': 32,
        'hidden_size': 96,
        'normalize_u': True,
        'normalize_v': False,
        'ln_before_gating': False,
        'gamma_start': 0.25,
        'gamma_end': 0.99,
        'a_max': 0.993
    }

class Wrapper:
    def __init__(self, **kwargs):
        self.model = Osc2CtxAdaptiveFactorizedL_LN(**kwargs)
        self.needs_rng = False
    def init(self, rng_key, dummy_input):
        return self.model.init(rng_key, dummy_input, training=True)
    def apply(self, params, x, training=False, mutable=None, rngs=None):
        if mutable is not None:
            return self.model.apply(params, x, training=training, mutable=mutable)
        return self.model.apply(params, x, training=training)

def create_network(hparams):
    return Wrapper(
        rank_k=int(hparams.get('rank_k', 320)),
        proj_rank=int(hparams.get('proj_rank', 32)),
        hidden_size=int(hparams.get('hidden_size', 96)),
        normalize_u=bool(hparams.get('normalize_u', True)),
        normalize_v=bool(hparams.get('normalize_v', False)),
        ln_before_gating=bool(hparams.get('ln_before_gating', False)),
        gamma_start=float(hparams.get('gamma_start', 0.25)),
        gamma_end=float(hparams.get('gamma_end', 0.99)),
        a_max=float(hparams.get('a_max', 0.993))
    )

def compute_loss(predictions, targets, params, x):
    return mae_with_temporal_curvature(predictions, targets, params, x, lam=1e-4)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate, eps=1e-8)
    )

def _to_array(v):
    # flax sow returns lists; take last if list
    if isinstance(v, (list, tuple)):
        return v[-1]
    return v

def complete(params, opt_state, trial_data):
    # Export full validation latents
    sys.path.append('storage/system')
    from train_single import load_data, create_batches
    # Recreate network for inference with latents collection
    hparams = trial_data.get('hyperparameters', {})
    net = create_network(hparams)

    # Load data
    _, val_data, _, val_labels = load_data()

    # Export dir
    tag = f"ln_ssm_k{hparams.get('rank_k',320)}_p{hparams.get('proj_rank',32)}_H{hparams.get('hidden_size',96)}_a{hparams.get('a_max',0.993)}_g{hparams.get('gamma_end',0.99)}"
    out_dir = os.path.join('storage', 'ariadne', 'analyses', 'latents', tag, f"trial_{trial_data.get('trial_number', 0)}_seed_{trial_data.get('seed', 0)}")
    os.makedirs(out_dir, exist_ok=True)

    fac_out_list, fac_pre_list, S_list = [], [], []
    gamma_vec = None

    for x_batch, _ in create_batches(val_data, 4, 32, BATCH_SIZE, val_labels, shuffle_key=None):
        preds, lat = net.apply(params, x_batch, training=False, mutable=['latents'])
        lat = lat.get('latents', {})
        f_out = _to_array(lat.get('factors_out'))
        f_pre = _to_array(lat.get('factors_preln'))
        Sgate = _to_array(lat.get('S_gate'))
        if gamma_vec is None:
            g = _to_array(lat.get('gamma'))
            if g is not None:
                gamma_vec = np.asarray(g)
        if f_out is not None:
            fac_out_list.append(np.asarray(f_out))
        if f_pre is not None:
            fac_pre_list.append(np.asarray(f_pre))
        if Sgate is not None:
            S_list.append(np.asarray(Sgate))

    if fac_out_list:
        factors_out = np.concatenate(fac_out_list, axis=0)
        np.savez_compressed(os.path.join(out_dir, 'factors_out.npz'), factors_out=factors_out)
    if fac_pre_list:
        factors_preln = np.concatenate(fac_pre_list, axis=0)
        np.savez_compressed(os.path.join(out_dir, 'factors_preln.npz'), factors_preln=factors_preln)
    if S_list:
        S_gate = np.concatenate(S_list, axis=0)
        np.savez_compressed(os.path.join(out_dir, 'S_gate.npz'), S_gate=S_gate)
    if gamma_vec is not None:
        np.save(os.path.join(out_dir, 'gamma.npy'), gamma_vec)

    # README with shapes
    with open(os.path.join(out_dir, 'README.txt'), 'w') as f:
        f.write("Latent export (full validation, non-shuffled windows):\n")
        f.write(f"factors_out.npz: (num_windows, 32, {hparams.get('rank_k',320)})\n")
        f.write(f"factors_preln.npz: (num_windows, 32, {hparams.get('rank_k',320)})\n")
        f.write(f"S_gate.npz: (num_windows, 32, {hparams.get('rank_k',320)})\n")
        f.write("gamma.npy: (32,)\n")
